        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.exit_code, None);
    }

    #[test]
    fn save_report_to_multiple_reports_are_separate_files() {
        let temp = tempfile::TempDir::new().unwrap();
        let report_a = build_report("step_a", "cmd_a", Some(1), "", "retry", &HashMap::new());
        let report_b = build_report("step_b", "cmd_b", Some(2), "", "retry", &HashMap::new());

        let path_a = save_report_to(&report_a, temp.path()).unwrap();
        let path_b = save_report_to(&report_b, temp.path()).unwrap();

        assert_ne!(path_a, path_b);
        assert!(path_a.exists());
        assert!(path_b.exists());
    }

    #[test]
    fn failure_report_serde_all_fields() {
        let report = FailureReport {
            step_name: "deploy".to_string(),
            command_scrubbed: "deploy.sh".to_string(),
            exit_code: Some(137),
            error_scrubbed: "OOM killed".to_string(),
            recovery_action: "skip".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(loaded.step_name, report.step_name);
        assert_eq!(loaded.command_scrubbed, report.command_scrubbed);
        assert_eq!(loaded.exit_code, report.exit_code);
        assert_eq!(loaded.error_scrubbed, report.error_scrubbed);
        assert_eq!(loaded.recovery_action, report.recovery_action);
        assert_eq!(loaded.bivvy_version, report.bivvy_version);
        assert_eq!(loaded.platform, report.platform);
    }
}
